import app from 'flarum/forum/app';
import { HERO_DEFAULTS, forumStats, fmtCount } from '../common/heroView';

/**
 * Work out which hero to show on the current discussion-list page, and merge the
 * three layers that produce it (highest priority first):
 *   1. the per-context overrides saved in the Hero Studio (`heroBuilder.heroes`)
 *   2. for a tag page, values derived from the tag itself (name / colour / icon)
 *   3. the forum-wide defaults
 * Returns null when the matching hero has been switched off.
 */
export function resolveHero() {
  const heroes = app.forum.attribute('heroBuilder.heroes') || {};
  const tag = currentTag();
  const ctxKey = tag ? 'tag:' + tag.id() : 'home';
  const override = heroes[ctxKey] || {};
  if (override.enabled === false) return null;
  const {
    base,
    stats
  } = baseLayer(tag);

  // Admin-defined custom stats (any context, incl. the home hero which has no
  // auto stat) take priority over the tag-derived count.
  const customStats = (Array.isArray(override.stats) ? override.stats : []).filter(s => s && (String(s.value ?? '').trim() !== '' || String(s.label ?? '').trim() !== '')).map(s => ({
    value: String(s.value ?? ''),
    icon: s.icon || 'fas fa-circle-info',
    label: s.label || ''
  }));
  return {
    title: override.title || base.title || '',
    // The server sends a subtitle with HTML in it as cleaned subtitleHtml instead.
    subtitle: override.subtitleHtml != null ? undefined : override.subtitle ?? base.subtitle,
    subtitleHtml: override.subtitleHtml || undefined,
    icon: override.icon || base.icon || HERO_DEFAULTS.icon,
    c1: override.c1 || base.c1 || HERO_DEFAULTS.c1,
    c2: override.c2 || base.c2 || HERO_DEFAULTS.c2,
    image: override.image || undefined,
    showStats: override.showStats !== false,
    stats: customStats.length ? customStats : stats,
    height: Number(override.height) || undefined,
    width: Number(override.width) || undefined,
    iconBg: override.iconBg !== false,
    sharpCorners: override.sharpCorners === true,
    borderWidth: override.borderWidth != null ? Number(override.borderWidth) : undefined,
    borderColor: override.borderColor || undefined,
    effects: override.effects || undefined,
    shadow: override.shadow || undefined,
    shadowCustom: override.shadowCustom || undefined,
    marginTop: override.marginTop != null ? Number(override.marginTop) : undefined,
    marginBottom: override.marginBottom != null ? Number(override.marginBottom) : undefined
  };
}

/**
 * The base layer and its automatic stats: derived from the tag on a tag page,
 * or from the forum (with the live forum totals) on the index.
 */
function baseLayer(tag) {
  const t = key => app.translator.trans(`ernestdefoe-hero-builder.forum.${key}`);
  if (tag) {
    const count = tag.discussionCount?.();
    return {
      base: {
        title: tag.name(),
        subtitle: tag.attribute('description') || '',
        icon: tag.attribute('icon') || HERO_DEFAULTS.icon,
        c1: tag.color() || HERO_DEFAULTS.c1,
        c2: HERO_DEFAULTS.c2
      },
      stats: typeof count === 'number' ? [{
        value: fmtCount(count),
        icon: 'fas fa-comments',
        label: t('discussions')
      }] : []
    };
  }
  return {
    base: {
      title: app.forum.attribute('title'),
      subtitle: app.forum.attribute('description') || '',
      icon: HERO_DEFAULTS.icon,
      c1: HERO_DEFAULTS.c1,
      c2: HERO_DEFAULTS.c2
    },
    stats: forumStats(app.forum.attribute('heroBuilderStats'), {
      discussions: t('discussions'),
      posts: t('posts'),
      members: t('members')
    })
  };
}

/** The tag whose page we're on, or null on the main index (or if tags is off). */
function currentTag() {
  const param = m.route.param('tags');
  if (!param || !app.store?.all) return null;
  const slug = String(param).split('/').pop();
  return app.store.all('tags').find(t => t.slug && t.slug() === slug) || null;
}